const complex=x=>Array.isArray(x)?{re:x[0],im:x[1]}:typeof x==='number'?{re:x,im:0}:x;
function formatComplex(input,digits=5){const z=complex(input),tol=.5*10**-digits;const num=x=>Math.abs(x)<tol?'0':Number(x.toFixed(digits)).toString();if(Math.abs(z.im)<tol)return num(z.re);const im=Math.abs(Math.abs(z.im)-1)<tol?'i':num(Math.abs(z.im))+'i';if(Math.abs(z.re)<tol)return(z.im<0?'−':'')+im;return num(z.re)+(z.im<0?' − ':' + ')+im;}
const cf=x=>{try{return formatComplex(complex(x),4)}catch{return JSON.stringify(x)}};
const norm=x=>Math.abs(x)<1e-8?0:Number(x.toFixed(6));
function fraction(n){if(!Number.isFinite(n))return '?';for(let d=1;d<=24;d++)if(Math.abs(n*d-Math.round(n*d))<1e-7)return d===1?String(Math.round(n)):Math.round(n*d)+'/'+d;return String(norm(n));}
function parseNumber(s){if(!/^\s*[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?(?:\s*\/\s*[+-]?(?:\d+\.?\d*|\.\d+))?\s*$/.test(s))throw new Error("coordinates only support numbers, decimals, or fractions, such as 1/2.");const a=s.split('/').map(Number);const n=a.length===2?a[0]/a[1]:a[0];if(!Number.isFinite(n)||Math.abs(n)>100)throw new Error("coordinates must be finite values ​​between −100 and 100.");return n;}
